<span class="line"><span style="color:#E06C75;">  displayName</span><span style="color:#ABB2BF;">: </span><span style="color:#E5C07B;">string</span><span style="color:#7F848E;font-style:italic;">    // 如 &quot;审批采购单&quot;</span></span>
