<span class="line"><span style="color:#E06C75;">  name</span><span style="color:#ABB2BF;">: </span><span style="color:#E5C07B;">string</span><span style="color:#7F848E;font-style:italic;">            // 如 &quot;采购经理&quot;</span></span>
